command:
set -euo pipefail; env_file="${UA_WHATBOX_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/upload-assistant/whatbox.env}"; set -a; source "$env_file"; set +a; export SSHPASS="$UA_WHATBOX_PASSWORD"; sshpass -e ssh -4 -o PubkeyAuthentication=no -o PreferredAuthentications=password -o StrictHostKeyChecking=yes artemisprime@destiny.whatbox.ca bash -s <<'REMOTE'
set -u
echo processes:
ps -eo pid,user,comm,args --sort=pid | grep -E '12345|upload|python|podman|conmon|web' | grep -v grep || true
echo user-services:
systemctl --user --no-pager --type=service --all 2>/dev/null | grep -Ei 'upload|web|podman' || true
echo privileged-socket-check:
sudo -n ss -ltnp 2>&1 | grep -E ':12345|:12346' || true
sudo -n fuser -v 12345/tcp 2>&1 || true
REMOTE
